package com.stockshield.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="orders",indexes={@Index(name="idx_order_status",columnList="status"),@Index(name="idx_order_created",columnList="createdAt")}) public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String orderCode; @ManyToOne(fetch=FetchType.LAZY,optional=false) private Product product; @Column(nullable=false) private int quantity; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status; @Column(nullable=false) private int retryCount; @Column(nullable=false) private String idempotencyKey; @Column(nullable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private Instant updatedAt=Instant.now();
public enum Status{CREATED,PROCESSING,SUCCESS,FAILED,OUT_OF_STOCK,RETRYING,DLQ}
public Long getId(){return id;} public String getOrderCode(){return orderCode;} public void setOrderCode(String v){orderCode=v;} public Product getProduct(){return product;} public void setProduct(Product v){product=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;updatedAt=Instant.now();} public int getRetryCount(){return retryCount;} public void setRetryCount(int v){retryCount=v;} public String getIdempotencyKey(){return idempotencyKey;} public void setIdempotencyKey(String v){idempotencyKey=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;}}
